import { existsSync, readFileSync, writeFileSync } from 'node:fs'
import { join, resolve } from 'node:path'
import { defineConfig, type Plugin } from 'vite'
import react from '@vitejs/plugin-react'

// The static pages (Upskill, About Us, Blogs, articles, original assets) are generated by scripts/build-site.mjs
// into .generated/public, which Vite serves in dev and copies into dist/ on build.
const PUBLIC_DIR = '.generated/public'

// Dev server: serve the static pages' directory indexes (e.g. /about-us/ → .generated/public/about-us/index.html),
// which Vite's public-dir handling does not do. In production the host serves dist/ directly.
function staticPages(): Plugin {
  return {
    name: 'taknikai-static-pages',
    apply: 'serve',
    configureServer(server) {
      server.middlewares.use((req, res, next) => {
        const path = decodeURIComponent((req.url ?? '/').split('?')[0])
        if (path === '/' || !path.endsWith('/')) return next()
        const file = join(server.config.root, PUBLIC_DIR, path, 'index.html')
        if (!existsSync(file)) return next()
        res.setHeader('Content-Type', 'text/html; charset=utf-8')
        res.end(readFileSync(file))
      })
    },
  }
}

// Writes dist/404.html: the React app renders its not-found page for any path other than "/".
function notFoundPage(): Plugin {
  let outDir = 'dist'
  return {
    name: 'taknikai-404',
    apply: 'build',
    configResolved(config) {
      outDir = resolve(config.root, config.build.outDir)
    },
    closeBundle(error?: Error) {
      // Rollup also calls closeBundle after a failed build; leave the real error visible
      if (error || !existsSync(join(outDir, 'index.html'))) return
      const html = readFileSync(join(outDir, 'index.html'), 'utf8')
        .replace(/<link rel="canonical"[^>]*>\s*/, '')
        .replace(/<meta name="robots" content="[^"]*" \/>/, '<meta name="robots" content="noindex" />')
        .replace(/<meta property="og:url"[^>]*>\s*/, '')
        .replace(/<title>[^<]*<\/title>/, '<title>Page not found | TaknikAI</title>')
      writeFileSync(join(outDir, '404.html'), html)
    },
  }
}

export default defineConfig({
  plugins: [react(), staticPages(), notFoundPage()],
  publicDir: PUBLIC_DIR,
  // Multi-page site: unknown paths must 404 rather than fall back to the homepage
  appType: 'mpa',
})
